    },
    {
      "name": "derivWithin_fun_sum",
      "module_name": "Mathlib.Analysis.Calculus.Deriv.Add",
      "kind": "theorem",
      "type": "∀ {𝕜 : Type u} [inst : NontriviallyNormedField 𝕜] {F : Type v} [inst_1 : NormedAddCommGroup F]\n  [inst_2 : NormedSpace 𝕜 F] {x : 𝕜} {s : Set 𝕜} {ι : Type u_1} {u : Finset ι} {A : ι → 𝕜 → F},\n  (∀ i ∈ u, DifferentiableWithinAt 𝕜 (A i) s x) →\n    derivWithin (fun y => ∑ i ∈ u, A i y) s x = ∑ i ∈ u, derivWithin (A i) s x"
    }
  ]
}

